"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["26611"],{93642(e){e.exports=JSON.parse('{"id":"FIN-965","slug":"divestiture","term":"Divestiture","also_known_as":[],"difficulty":"Intermediate","definition":"A divestiture is the sale or disposal of a business unit, subsidiary, division or assets by a company.","explanation":["Companies divest parts of their businesses for many reasons. They may want to focus on their core activities, raise cash to reduce debt or fund other investments, exit underperforming or unprofitable businesses, or respond to regulatory requirements.","Divestitures can take several forms. A company can sell a division to another company or to a private equity firm. It can spin off the division as a separate company, giving shares to its existing shareholders. Or it can sell shares in the division to the public through a partial listing, sometimes called a carve-out.","For example, a consumer goods company might sell its food brands to focus on beauty and personal care products, using the proceeds to invest in its remaining businesses.","Competition authorities sometimes require companies to divest parts of their businesses as a condition of approving a merger, to preserve competition.","Divestitures can create value when the business being sold is worth more to another owner, or when the remaining company becomes simpler and more focused, making it easier for investors to understand and value."],"note":"","total":1500,"prev":{"slug":"diversification","term":"Diversification"},"next":{"slug":"dividend","term":"Dividend"}}')}}]);